/// Every piece of Fortnite content the mashup uses. Nothing here ships with the mod: the setup tool finds each row in the player's own Fortnite install (query = regex over package paths, '-> Prop' = foll
#[derive(Debug)]
pub struct FortniteAssetsRow {
    /// key
    pub id: &'static str,
    /// skeletal_mesh | static_mesh | anim | texture | sound | font
    pub kind: &'static str,
    /// how the extractor finds it in the install
    pub query: &'static str,
    /// file under the cache folder
    pub out: &'static str,
    /// setup fails if missing (otherwise a fallback is drawn)
    pub required: bool,
}

