/// What the pickaxe harvests. The DLL ray-casts the swing against the map; the hit asset's name (AEG id) picks the row by prefix. Fortnite yields per hit; hitting the weak point (critical) doubles it.
#[derive(Debug)]
pub struct HarvestablesRow {
    /// key
    pub id: &'static str,
    /// AEG name prefixes or map-collision material that count
    pub matches: &'static [&'static str],
    /// @materials row
    pub material: usize,
    /// material per swing
    pub per_hit: u32,
    /// material per weak-point swing
    pub crit_per_hit: u32,
    /// swings before it stops yielding (0 = endless, used for terrain)
    pub hits_to_break: u32,
    /// seconds before it yields again
    pub respawn_s: f32,
}

