pub struct HudRow {
    /// key
    pub id: &'static str,
    /// [x, y] anchor, screen fraction
    pub pos: [f32; 2],
    /// [w, h] screen fraction
    pub size: [f32; 2],
    /// what it shows
    pub source: &'static str,
    /// @fortnite_assets row (or none)
    pub art: Option<usize>,
    /// always | combat | build | when_relevant
    pub visible: &'static str,
}

