/// Fortnite building materials. HP values are Fortnite's max wall HP per material; build_s is how long a piece takes to reach full HP.
#[derive(Debug)]
pub struct MaterialsRow {
    /// key
    pub id: &'static str,
    /// display name
    pub name: &'static str,
    /// carry cap
    pub max: u32,
    /// cost per build piece
    pub piece_cost: u32,
    /// max HP of a wall
    pub wall_hp: u32,
    /// max HP of a floor
    pub floor_hp: u32,
    /// max HP of a ramp
    pub ramp_hp: u32,
    /// HP fraction when placed
    pub start_hp_frac: f32,
    /// seconds to reach full HP
    pub build_s: f32,
    /// @fortnite_assets row
    pub fn_icon: usize,
    /// @fortnite_assets row: build-piece texture set
    pub fn_material_tex: usize,
}

