/// How loot scales through the Lands Between so Fortnite guns keep up with Elden Ring's enemies. A gun's Elden Ring damage = weapons.damage[rarity] x damage_mult of the tier it was found in. Tier is pick
#[derive(Debug)]
pub struct RegionTiersRow {
    /// key
    pub id: &'static str,
    /// where
    pub name: &'static str,
    /// map ids in this tier: mAA or mAA_BB (legacy dungeons/underground), or m60_X0-X1_Z0-Z1 (open-world tile ranges); first match wins
    pub map_areas: &'static [&'static str],
    /// gun damage multiplier
    pub damage_mult: f32,
    /// 5 weights
    pub rarity_weights: [f32; 5],
    /// typical field-enemy HP there (design note, for balance)
    pub enemy_hp_hint: f32,
}

