/// Where containers appear. Anchors are every Site of Grace in the game (BonfireWarpParam rows hold each grace's map tile and position), so placement covers the whole game, DLC included, without a hand-m
#[derive(Debug)]
pub struct SpawnRulesRow {
    /// key
    pub id: &'static str,
    /// what a container is placed next to: grace
    pub anchor: &'static str,
    /// containers per anchor
    pub count: u32,
    /// chance each one exists (deterministic per anchor+index)
    pub chance: f32,
    /// distance from the anchor
    pub offset_m: f32,
    /// no two containers closer than this
    pub min_spacing_m: f32,
    /// never | on_rest (resting at grace refills)
    pub respawn: &'static str,
}

