/// Every Elden Ring system the mashup touches, and how. One row = one hook/module in the DLL (fortring/src/systems/<id>.rs). er_api names the fromsoftware-rs type or the Windows API used.
#[derive(Debug)]
pub struct SystemsRow {
    /// key
    pub id: &'static str,
    /// what it does for the player
    pub what: &'static str,
    /// engine object / API it reads or writes
    pub er_api: &'static str,
    /// game task group or hook point
    pub when: &'static str,
    /// list of @systems rows
    pub depends: &'static [usize],
    /// sheets it reads
    pub sheets: &'static [&'static str],
    /// version
    pub release: &'static str,
}

