/// One row per Fortnite gun. Damage is Fortnite's per-shot body damage by rarity [common, uncommon, rare, epic, legendary]; the DLL multiplies it by the region tier where the gun was found (region_tiers.
#[derive(Debug)]
pub struct WeaponsRow {
    /// stable key used by code and other sheets
    pub id: &'static str,
    /// display name on the HUD
    pub name: &'static str,
    /// fire behaviour family: rifle | shotgun | smg | sniper | pistol | launcher
    pub class: &'static str,
    /// @ammo row
    pub ammo: usize,
    /// body damage per shot (shotgun: whole shot) by rarity, 5 numbers
    pub damage: [f32; 5],
    /// headshot multiplier
    pub headshot_mult: f32,
    /// projectiles per shot
    pub pellets: u32,
    /// shots per second
    pub fire_rate: f32,
    /// true = hold to fire
    pub auto: bool,
    /// magazine size
    pub mag: u32,
    /// reload time in seconds by rarity, 5 numbers
    pub reload_s: [f32; 5],
    /// true = reloads one round at a time (pump)
    pub reload_per_shell: bool,
    /// max effective range in metres (bullet life)
    pub range_m: f32,
    /// distance where damage starts to drop
    pub falloff_start_m: f32,
    /// damage fraction at range_m
    pub falloff_min: f32,
    /// cone half-angle hip fire
    pub spread_hip_deg: f32,
    /// cone half-angle aiming down sights
    pub spread_ads_deg: f32,
    /// spread added per shot
    pub bloom_per_shot_deg: f32,
    /// camera kick per shot
    pub recoil_pitch_deg: f32,
    /// projectile speed (hitscan guns use a fast engine bullet)
    pub bullet_speed_mps: f32,
    /// 0 = no splash
    pub explosion_radius_m: f32,
    /// multiplier against player builds
    pub build_damage_mult: f32,
    /// camera FOV while aiming
    pub ads_fov: f32,
    /// which rarities can drop: list of @rarities ids
    pub rarities: &'static [usize],
    /// @fortnite_assets row for the weapon mesh
    pub fn_mesh: usize,
    /// @fortnite_assets row for the HUD icon
    pub fn_icon: usize,
    /// @fortnite_assets row
    pub fn_fire_sound: usize,
    /// @fortnite_assets row
    pub fn_reload_sound: usize,
    /// @animations group for fire/reload
    pub anim_set: usize,
}

